sql.where:
m.deleted = 0



    AND m.market_id = #{reqVO.marketId}


    AND m.name LIKE CONCAT('%', #{reqVO.name}, '%')


    AND m.address LIKE CONCAT('%', #{reqVO.address}, '%')


    AND m.area_code = #{reqVO.areaCode}


    AND m.stall_count = #{reqVO.stallCount}


    AND m.manager_id = #{reqVO.managerId}


    AND m.operation_status_id = #{reqVO.operationStatusId}




    AND m.hygiene_rate = #{reqVO.hygieneRate}


    AND m.waste_transfer_rate = #{reqVO.wasteTransferRate}


    AND m.sewage_rate = #{reqVO.sewageRate}


    AND m.unfinished_task_count = #{reqVO.unfinishedTaskCount}




    AND m.cleaning_frequency LIKE CONCAT('%', #{reqVO.cleaningFrequency}, '%')



    AND m.cleaning_time LIKE CONCAT('%', #{reqVO.cleaningTime[0]}, '%')


    AND m.cleaning_area LIKE CONCAT('%', #{reqVO.cleaningArea}, '%')


    AND m.staff_ids LIKE CONCAT('%', #{reqVO.staffIds}, '%')


    AND m.cleaning_standard LIKE CONCAT('%', #{reqVO.cleaningStandard}, '%')


    AND m.garbage_type_ids LIKE CONCAT('%', #{reqVO.garbageTypeIds}, '%')


    AND m.garbage_container_count = #{reqVO.garbageContainerCount}


    AND m.waste_transfer_interval LIKE CONCAT('%', #{reqVO.wasteTransferInterval}, '%')


    AND m.waste_transfer_time LIKE CONCAT('%', #{reqVO.wasteTransferTime[0]}, '%')


    AND m.vehicle_id = #{reqVO.vehicleId}


    AND m.sewage_discharge_area LIKE CONCAT('%', #{reqVO.sewageDischargeArea}, '%')


    AND m.sewage_disposal_way LIKE CONCAT('%', #{reqVO.sewageDisposalWay}, '%')


    AND m.sewage_cleaning_frequency LIKE CONCAT('%', #{reqVO.sewageCleaningFrequency}, '%')


    AND m.sewage_problem_desc LIKE CONCAT('%', #{reqVO.sewageProblemDesc}, '%')




    AND m.last_sewage_cleaning_time BETWEEN #{reqVO.lastSewageCleaningTime[0]} AND #{reqVO.lastSewageCleaningTime[1]}


    AND m.next_sewage_cleaning_time BETWEEN #{reqVO.nextSewageCleaningTime[0]} AND #{reqVO.nextSewageCleaningTime[1]}



    AND m.sewage_disposal_log LIKE CONCAT('%', #{reqVO.sewageDisposalLog}, '%')



    AND m.hygiene_check_time LIKE CONCAT('%', #{reqVO.hygieneCheckTime[0]}, '%')



    AND m.check_by = #{reqVO.checkBy}



    AND m.hygiene_check_date BETWEEN #{reqVO.hygieneCheckDate[0]} AND #{reqVO.hygieneCheckDate[1]}



    AND m.previous_problem LIKE CONCAT('%', #{reqVO.previousProblem}, '%')


    AND m.qualified_item_count = #{reqVO.qualifiedItemCount}


    AND m.unqualified_item_count = #{reqVO.unqualifiedItemCount}


    AND m.reform_require LIKE CONCAT('%', #{reqVO.reformRequire}, '%')


    AND DATE(m.reform_deadline) = DATE(#{reqVO.reformDeadline})




    AND m.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
